import csv, json, math, statistics
from pathlib import Path
from collections import Counter
root=Path('code/V4/runs/R70_latent_mixup')
prior=root.parent/'R69_task_specific_finetuning'
read=lambda p: json.loads(Path(p).read_text())
rows=lambda name: list(csv.DictReader((root/name).open(newline='')))
metrics=('top1','top2','top3','ce','mean_cost','actual_regret_pct','vs_sbs_pct')
res={'A':read(prior/'B_task_specific_seed2/result.json'),'B':read(root/'B_latent_mixup_seed2/result.json')}
hist={'A':read(root/'reused_A_history.json'),'B':read(root/'B_latent_mixup_seed2/history.json')}
tests=read(root/'test_results.json')
records={f'R70{a}_'+('reused_R69B20' if a=='A' else 'latent_mixup'):dict(epoch=r['best']['epoch'], train=r['best']['train'],val=r['best']['val'],test=tests['models'][a]) for a,r in res.items()}
prov=read(root/'reference_provenance.json')['references']
for name in ('R45A','R60B'):
    saved=read(prov[name]['saved_reference_path'])
    records[name]=dict(epoch=saved['selected_epoch'],val=saved['validation'],test=saved['test'],train=read(prov[name]['train_source']['path'])['best'].get('train'))
for name,a in (('R64A','A'),('R64B','B')):
    best=read(prov[name]['result_path'])['best']
    records[name]=dict(epoch=best['epoch'],train=best['train'],val=best['val'],test=read(prov[name]['test_path'])['models'][a])
def value(evaluation,kind,scope,key):
    if kind=='aggregate': return evaluation['macro']['macro_'+key]
    if kind=='family': return evaluation['families'][scope]['macro_'+key]
    return evaluation['per_problem'][scope][key]
errors=[]
counts={}
def compare(label,actual,expected):
    if not math.isclose(float(actual),float(expected),rel_tol=1e-12,abs_tol=1e-12):
        errors.append([label,actual,expected])
comparison=rows('comparison.csv')
for i,row in enumerate(comparison,2):
    e=records[row['model']][row['split']]
    for key in metrics: compare(['comparison',i,key],row[key],value(e,row['kind'],row['scope'],key))
    compare(['comparison',i,'epoch'],row['epoch'],records[row['model']]['epoch'])
counts['comparison_rows']=len(comparison)
counts['comparison_metric_values']=len(comparison)*len(metrics)
for i,row in enumerate(rows('learning_curves.csv'),2):
    e=res[row['arm']]['best']['train'] if row['measurement']=='actual selected-best TRAIN' else hist[row['arm']][int(row['epoch'])-1][row['split']]
    for key in metrics: compare(['learning',i,key],row[key],value(e,row['kind'],row['scope'],key))
counts['learning_rows']=len(rows('learning_curves.csv'))
functions={'last5_mean':statistics.mean,'last5_population_sd':statistics.pstdev,'last5_min':min,'last5_max':max}
for i,row in enumerate(rows('stage2_summary.csv'),2):
    for key in metrics:
        if row['summary'] in ('best','final'):
            expected=value(res[row['arm']][row['summary']][row['split']],row['kind'],row['scope'],key)
        else:
            expected=functions[row['summary']]([value(h['val'],row['kind'],row['scope'],key) for h in hist[row['arm']][-5:]])
        compare(['summary',i,key],row[key],expected)
counts['summary_rows']=len(rows('stage2_summary.csv'))
for i,row in enumerate(rows('matched_common_epochs.csv'),2):
    for key in metrics:
        actual=[]
        for arm in ('A','B'):
            e=hist[arm][int(row['epoch'])-1][row['split']]
            if e is None: e=res[arm]['best'][row['split']]
            actual.append(value(e,row['kind'],row['scope'],key))
            compare(['common',i,arm,key],row[arm+'_'+key],actual[-1])
        compare(['common',i,'delta',key],row[key+'_B_minus_A'],actual[1]-actual[0])
counts['common_epoch_rows']=len(rows('matched_common_epochs.csv'))
indexed={(r['model'],r['split'],r['kind'],r['scope']):r for r in comparison}
for i,row in enumerate(rows('comparison_deltas.csv'),2):
    a=indexed[(row['left_model'],row['split'],row['kind'],row['scope'])]
    b=indexed[(row['right_model'],row['split'],row['kind'],row['scope'])]
    for key in metrics:
        suffix='_delta_pp' if key.startswith('top') else '_delta'
        compare(['delta',i,key],row[key+suffix],(float(a[key])-float(b[key]))*(100 if key.startswith('top') else 1))
counts['delta_rows']=len(rows('comparison_deltas.csv'))
newfile=root/'B_latent_mixup_seed2/updates.jsonl'
oldfile=prior/'B_task_specific_seed2/updates.jsonl'
sums=Counter(); schedule_differences=[]; attempt_events=[]
with newfile.open() as new,oldfile.open() as old:
    for i,(new_line,old_line) in enumerate(zip(new,old),1):
        n,o=json.loads(new_line),json.loads(old_line)
        for key in ('successful_update','tasks','task_rows','rows','actual_forward_rows','batch_indices_sha256','dropout_seed','lr','consistency_weight'):
            if n[key]"'!=o[key]:schedule_differences.append([i,key])
        for key in ('"'rows','successful_view_rows','attempted_view_rows','successful_mixed_head_rows','attempted_mixed_head_rows','retries','base_optimizer_steps'):
            sums[key]+=n[key]
        if n['successful_update']"'!=i: errors.append(['"'update_order',i,n['successful_update']])
        if n['retries']: attempt_events.append([i,n['retries']])
        compare(['loss',i],n['loss'],.5*n['clean_ce']+.5*n['mix_ce']+n['consistency_weight']*n['kl'])
counts['update_records']=i
print(json.dumps(dict(saved_table_rows=counts,numeric_mismatches=len(errors),first_mismatches=errors[:8],stored_schedule_differences=schedule_differences[:8],stored_update_totals=sums,retry_events=attempt_events,control_history_exactly_equal=(hist['A']==read(prior/'B_task_specific_seed2/history.json')),control_test_object_exactly_equal=(tests['models']['A']==read(prior/'test_results.json')['models']['B'])),indent=2))
PY"

